// DeliveryReceipt The immutable record of one attempt to deliver a release manifest to one output: a feed snapshot, the website, the media edge, or an external destination. Receipts reference the manifest; the manifest never references receipts. Delivery state is derived from the receipts (model/state-machines.md §5).
type DeliveryReceipt struct {
	Attempt int `json:"attempt"`

	// Edge Required for a delivered media_edge output: the HEAD and byte-range checks of the enclosure URL.
	Edge *struct {
		// Checks Named verification checks and whether each passed, for example guidPreserved, enclosureLengthMatches.
		Checks        DeliveryReceiptChecks `json:"checks"`
		ContentLength int                   `json:"contentLength"`
		ContentType   string                `json:"contentType"`
		RangeStatus   int                   `json:"rangeStatus"`
		Status        int                   `json:"status"`
		Url           string                `json:"url"`
	} `json:"edge,omitempty"`
	EpisodeId DeliveryReceiptUuid `json:"episodeId"`

	// Error Required when result is `failed`. A problem+json-shaped summary, redacted of tokens and signed URLs.
	Error *struct {
		Detail    *string `json:"detail,omitempty"`
		Retryable bool    `json:"retryable"`
		Title     string  `json:"title"`
		Type      string  `json:"type"`
	} `json:"error,omitempty"`

	// External What the destination returned. Values are opaque data.
	External *struct {
		// ConfirmedBy For a manual confirmation: the staff user who recorded it.
		ConfirmedBy *DeliveryReceiptUuid `json:"confirmedBy,omitempty"`
		ExternalId  *string              `json:"externalId,omitempty"`
		ExternalUrl *string              `json:"externalUrl,omitempty"`
	} `json:"external,omitempty"`

	// FeedSnapshot Required for a delivered feed snapshot: the object that was written and verified.
	FeedSnapshot *struct {
		Bytes int `json:"bytes"`

		// Checks Named verification checks and whether each passed, for example guidPreserved, enclosureLengthMatches.
		Checks         DeliveryReceiptChecks              `json:"checks"`
		FeedSnapshotId DeliveryReceiptUuid                `json:"feedSnapshotId"`
		Generation     int                                `json:"generation"`
		ObjectKey      string                             `json:"objectKey"`
		Sha256         DeliveryReceiptSha256              `json:"sha256"`
		Variant        DeliveryReceiptFeedSnapshotVariant `json:"variant"`
	} `json:"feedSnapshot,omitempty"`

	// IdempotencyKey `{output}:{manifestId}` for owned outputs, `{publicationTargetId}:{manifestId}` for destinations. Retries reuse it.
	IdempotencyKey string              `json:"idempotencyKey"`
	ManifestId     DeliveryReceiptUuid `json:"manifestId"`

	// ManifestSha256 SHA-256 of the manifest's RFC 8785 canonical JSON, so a receipt proves which exact manifest it delivered.
	ManifestSha256 DeliveryReceiptSha256    `json:"manifestSha256"`
	OccurredAt     DeliveryReceiptTimestamp `json:"occurredAt"`
	Output         struct {
		// DestinationKey The destination's key, as data (for example `youtube`). Never a type.
		DestinationKey      *string                   `json:"destinationKey,omitempty"`
		Kind                DeliveryReceiptOutputKind `json:"kind"`
		PublicationTargetId *DeliveryReceiptUuid      `json:"publicationTargetId,omitempty"`
	} `json:"output"`
	ReceiptId DeliveryReceiptUuid `json:"receiptId"`

	// Result Owned outputs end in `delivered` or `failed`. Destinations use `submitted`, `confirmed`, `failed`, `manual_required`, or `withdrawn`.
	Result        DeliveryReceiptResult        `json:"result"`
	SchemaVersion DeliveryReceiptSchemaVersion `json:"schemaVersion"`
}

// DeliveryReceiptFeedSnapshotVariant defines model for DeliveryReceipt.FeedSnapshot.Variant.
type DeliveryReceiptFeedSnapshotVariant string

// DeliveryReceiptOutputKind defines model for DeliveryReceipt.Output.Kind.
type DeliveryReceiptOutputKind string

// DeliveryReceiptResult Owned outputs end in `delivered` or `failed`. Destinations use `submitted`, `confirmed`, `failed`, `manual_required`, or `withdrawn`.
type DeliveryReceiptResult string

// DeliveryReceiptSchemaVersion defines model for DeliveryReceipt.SchemaVersion.
type DeliveryReceiptSchemaVersion string

